def choose_move(observation):
    def _pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def _xy_list(items):
        out = []
        for p in items or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                out.append((p[0], p[1]))
            elif isinstance(p, dict):
                if "x" in p and "y" in p:
                    out.append((p["x"], p["y"]))
        return out

    sx, sy = _pos(observation.get("self_position"), (0, 0))
    ox, oy = _pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    obstacles = set(_xy_list(observation.get("obstacles")))
    resources = _xy_list(observation.get("resources"))
    targets = []
    for key in (
        "resource_positions", "resource_locations", "food", "foods",
        "treasures", "items", "powerups", "control_points", "capture_points",
        "neutral_points", "territory_targets", "objectives", "goals"
    ):
        targets.extend(_xy_list(observation.get(key)))

    owned = set(_xy_list(observation.get("owned_cells")))
    territory = set(_xy_list(observation.get("territory")))
    enemy_territory = set(_xy_list(observation.get("enemy_territory")))
    unexplored = set(_xy_list(observation.get("unexplored")))
    targets.extend(resources)

    def _inside(x, y):
        if gw and (x < 0 or x >= gw):
            return False
        if gh and (y < 0 or y >= gh):
            return False
        return True

    def _blocked(x, y):
        return (x, y) in obstacles

    def _md(a, b, c, d):
        return abs(a - c) + abs(b - d)

    # Build candidate actions.
    actions = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            actions.append((dx, dy))

    # Determine tactical mode.
    has_resources = len(resources) > 0
    has_territory = bool(territory or owned or enemy_territory or unexplored or observation.get("territory_control") is not None)
    opp_dist = _md(sx, sy, ox, oy)

    threatened = False
    if opp_dist <= 2:
        threatened = True
    if observation.get("self_health") is not None and observation.get("opponent_health") is not None:
        if observation.get("self_health", 0) < observation.get("opponent_health", 0) and opp_dist <= 4:
            threatened = True

    # Choose a primary target if any.
    primary = None
    if has_resources:
        bestv = None
        for tx, ty in resources:
            d1 = _md(sx, sy, tx, ty)
            d2 = _md(ox, oy, tx, ty)
            v = (d1 - d2, d1, tx, ty)
            if bestv is None or v < bestv:
                bestv = v
                primary = (tx, ty)
    elif targets:
        bestv = None
        for tx, ty in targets:
            d1 = _md(sx, sy, tx, ty)
            v = (d1, tx, ty)
            if bestv is None or v < bestv:
                bestv = v
                primary = (tx, ty)
    else:
        # Explore center / away from opponent depending on mode.
        if has_territory:
            if gw and gh:
                primary = (gw // 2, gh // 2)
            else:
                primary = (sx + (1 if sx <= ox else -1), sy + (1 if sy <= oy else -1))
        else:
            primary = (ox, oy) if not threatened else (sx - (1 if ox > sx else -1 if ox < sx else 0),
                                                      sy - (1 if oy > sy else -1 if oy < sy else 0))

    best_move = [0, 0]
    best_score = None

    for dx, dy in actions:
        nx, ny = sx + dx, sy + dy
        if not _inside(nx, ny) or _blocked(nx, ny):
            continue

        score = 0

        # Prefer moving toward target if available.
        if primary is not None:
            curd = _md(sx, sy, primary[0], primary[1])
            newd = _md(nx, ny, primary[0], primary[1])
            score += (curd - newd) * 10

        # Resource collection: reward closer resource and slight opponent competition avoidance.
        if has_resources:
            best_after = None
            for tx, ty in resources:
                d = _md(nx, ny, tx, ty)
                v = (d, tx, ty)
                if best_after is None or v < best_after:
                    best_after = v
            if best_after is not None:
                score += (20 - best_after[0]) if best_after[0] < 20 else 0
                if _md(nx, ny, ox, oy) <= best_after[0]:
                    score += 2

        # Pursuit/evasion.
        if threatened:
            score += _md(nx, ny, ox, oy) * 6
        else:
            score += max(0, 6 - _md(nx, ny, ox, oy))

        # Territory control: prefer unowned/unexplored/frontier.
        if has_territory:
            if (nx, ny) in owned:
                score -= 2
            if (nx, ny) in territory:
                score += 2
            if (nx, ny) in enemy_territory:
                score += 4
            if (nx, ny) in unexplored:
                score += 3
            if gw and gh:
                cx, cy = gw // 2, gh // 2
                score += max(0, 8 - _md(nx, ny, cx, cy)) // 2

        # Mild exploration if stuck.
        score += (dx != 0 or dy != 0)

        # Avoid oscillation-like stillness unless necessary.
        if dx == 0 and dy == 0:
            score -= 1 if primary is not None else 0

        if best_score is None or score > best_score:
            best_score = score
            best_move = [dx, dy]

    return best_move

