    trail = set(pts(observation.get("self_path"))[-6:])
    dirs = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]

    def score(dx, dy):
        nx, ny = sx + dx, sy + dy
        if nx < 0 or ny < 0 or (gw and nx >= gw) or (gh and ny >= gh): return -10**9
        if (nx, ny) in obs: return -10**9
        s = 0
